{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C43"],
      "claim": "Propafenone, a secondary-amine aromatic drug with the highest assay-transfer score (0.8742), showed absolute oral bioavailability of 15% in a patient vs IV, below the 20% threshold, attributed to extensive presystemic metabolism; this supports low bioavailability for the query's secondary-amine/aromatic structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "DMT, an indole-containing basic amine with high transfer (0.8234), had absolute oral bioavailability of only about 10-15% when given orally, supporting low bioavailability for the query's indole and basic amine features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Sumatriptan, an indole-based basic amine with transfer 0.7121, had absolute oral bioavailability of 14% (10-26%) after a 100 mg oral dose, supporting low bioavailability for the query's indole and secondary-amine pharmacophore.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Epanolol, a secondary-amine aryloxypropanolamine with transfer 0.6857, had mean oral bioavailability of 5.85 ± 2.55% with food due to first-pass hepatic clearance, supporting low bioavailability for the query's secondary-amine and polar functionality.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C70"],
      "claim": "Agomelatine, an amide-containing lipophilic drug with transfer 0.6756, has absolute oral bioavailability of only about 3-4% in humans due to first-pass metabolism, supporting low bioavailability for the query's amide/hydroxamic-acid-like moiety.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Eluxadoline, a zwitterionic drug with transfer 0.664, has oral bioavailability of 1.02% due to low GI permeability and hepatic first-pass extraction; the query's combination of a basic secondary amine and acidic hydroxamic acid may similarly limit absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Ketanserin, with transfer 0.6674, had absolute oral bioavailability of 55.5% in healthy subjects, showing that some basic aromatic drugs can exceed 20%; however, its lower transfer and lack of the query's indole/hydroxamic acid combination reduce its weight.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The preponderance of high-transfer experimental evidence from structurally related secondary-amine/indole-containing drugs (propafenone, DMT, sumatriptan, epanolol, agomelatine, eluxadoline) shows absolute oral bioavailability well below 20%, often due to presystemic metabolism and/or poor permeability. The query's basic secondary amine plus polar hydroxamic acid is expected to have similarly low F. Contradictory high-F analogues are less transferable and structurally less relevant.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule.",
    "No human PK data are available for the exact indole-secondary amine-hydroxamic acid combination.",
    "Uncertainty remains about whether the hydroxamic acid moiety could be absorbed or metabolically stable enough to reach F >= 20%.",
    "High-F analogues (ketanserin, tadalafil, fluvastatin) have lower transfer scores and lack the query's ionizable hydroxamic acid/secondary amine combination."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

